<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import { clearAdminSession, deleteNews, deletePerson, getAllNews, getPeople, getSettings, hasAdminSession, hasContentRole, isSupabaseConfigured, saveNews, savePerson, saveSettings, signIn, uploadNewsImage } from '../services/contentService.js'

const router = useRouter()
const configured = isSupabaseConfigured()
const authenticated = ref(hasAdminSession() && hasContentRole())
const email = ref(''); const password = ref(''); const error = ref(''); const busy = ref(false)
const tab = ref('news'); const news = ref([]); const people = ref([]); const settings = reactive({}); const editorOpen = ref(false); const editing = ref(null)
const uiLanguage = ref(localStorage.getItem('school13-admin-language') || 'ru')
const labels = computed(() => uiLanguage.value === 'uz' ? {
  back: '← Saytga', login: 'Panelga kirish', loginHint: 'Supabase administrator akkauntingiz bilan kiring.', email: 'Email', password: 'Parol', signIn: 'Kirish', signingIn: 'Kirilmoqda…',
  manage: 'BOSHQARUV', news: 'Yangiliklar', people: 'Jamoa', school: 'Maktab haqida', viewSite: '↗ Saytni ko‘rish', logout: 'Chiqish', allNews: 'Barcha nashrlar', newsHint: 'Yangiliklarni o‘zbek va rus tillarida yarating.', newNews: '＋ Yangi yangilik', editNews: 'Yangilikni tahrirlash', draft: 'Qoralama', published: 'Chop etilgan', category: 'Toifa', slug: 'Havola (slug)', title: 'Sarlavha', categoryName: 'Toifa nomi', excerpt: 'Qisqacha mazmun', body: 'Yangilik matni', bodyHint: 'Xatboshilarni bo‘sh qator bilan ajrating', photo: 'Asosiy rasm', upload: 'Rasm tanlash', removePhoto: 'Rasmni olib tashlash', photoHint: 'JPG, PNG yoki WebP · 5 MB gacha. Rasm bosh sahifa va yangilik sahifasida ko‘rinadi.', saveNews: 'Yangilikni saqlash', close: 'Yopish ×', edit: 'Tahrirlash', delete: 'O‘chirish', noNews: 'Hozircha yangiliklar yo‘q. Birinchi yangilikni qo‘shing.', teamTitle: 'O‘qituvchilar va o‘quvchilar', teamHint: 'Yozuvlar saytdagi jamoa bo‘limida ko‘rinadi.', addPerson: '＋ Odam qo‘shish', personCard: 'Jamoa kartasi', type: 'Turi', personPhoto: 'Foto (URL)', order: 'Tartib', name: 'Ism / sarlavha', role: 'Lavozim yoki yutuq', quote: 'Iqtibos', save: 'Saqlash', noPeople: 'Hozircha jamoa yozuvlari yo‘q.', schoolTitle: 'Maktab haqida', schoolHint: 'Bu matn saytdagi asosiy bo‘limda ikki tilda ko‘rinadi.', heading: 'Sarlavha', text: 'Matn', saveSchool: 'Ma’lumotni saqlash', connected: 'Supabase', local: 'Mahalliy rejim', demo: 'Demo rejimi: o‘zgarishlar shu brauzerda saqlanadi.', savedNews: 'Yangilik saqlandi', savedSchool: 'Maktab ma’lumoti saqlandi', categorySchool: 'Maktab hayoti', categoryStudents: 'O‘quvchilar', categoryEvents: 'Tadbirlar', teacher: 'O‘qituvchi', student: 'O‘quvchi', stats: 'Statistika yozuvi'
} : {
  back: '← На сайт', login: 'Вход в панель', loginHint: 'Войдите с учётной записью администратора Supabase.', email: 'Email', password: 'Пароль', signIn: 'Войти', signingIn: 'Входим…',
  manage: 'УПРАВЛЕНИЕ', news: 'Новости', people: 'Команда', school: 'О школе', viewSite: '↗ Посмотреть сайт', logout: 'Выйти', allNews: 'Все публикации', newsHint: 'Создавайте новости на узбекском и русском языках.', newNews: '＋ Новая новость', editNews: 'Редактировать новость', draft: 'Черновик', published: 'Опубликована', category: 'Категория', slug: 'Ссылка (slug)', title: 'Заголовок', categoryName: 'Название категории', excerpt: 'Краткое описание', body: 'Текст новости', bodyHint: 'Абзацы разделяйте пустой строкой', photo: 'Главное фото', upload: 'Выбрать фото', removePhoto: 'Убрать фото', photoHint: 'JPG, PNG или WebP · до 5 МБ. Фото появится на главной и на странице новости.', saveNews: 'Сохранить новость', close: 'Закрыть ×', edit: 'Редактировать', delete: 'Удалить', noNews: 'Новостей пока нет. Добавьте первую публикацию.', teamTitle: 'Учителя и ученики', teamHint: 'Записи появятся в секции команды на сайте.', addPerson: '＋ Добавить человека', personCard: 'Карточка команды', type: 'Тип', personPhoto: 'Фото (URL)', order: 'Порядок', name: 'Имя / заголовок', role: 'Роль или достижение', quote: 'Цитата', save: 'Сохранить', noPeople: 'Записей о команде пока нет.', schoolTitle: 'О школе', schoolHint: 'Этот текст виден в основном блоке сайта на двух языках.', heading: 'Заголовок', text: 'Текст', saveSchool: 'Сохранить информацию', connected: 'Supabase', local: 'Локальный режим', demo: 'Демо-режим: изменения сохраняются в этом браузере.', savedNews: 'Новость сохранена', savedSchool: 'Информация о школе сохранена', categorySchool: 'Жизнь школы', categoryStudents: 'Ученики', categoryEvents: 'События', teacher: 'Учитель', student: 'Ученик', stats: 'Подпись статистики'
})
function setUiLanguage(value) { uiLanguage.value = value; localStorage.setItem('school13-admin-language', value) }
const imageBusy = ref(false)
const blankNews = () => ({ id: null, slug: '', status: 'draft', publishedAt: new Date().toISOString(), category: 'school', cover: { type: 'pattern', theme: 'school', imageUrl: '' }, translations: { uz: { categoryLabel: 'Maktab hayoti', title: '', excerpt: '', body: [''] }, ru: { categoryLabel: 'Жизнь школы', title: '', excerpt: '', body: [''] } } })
const blankPerson = () => ({ id: null, role: 'teacher', photo_url: '', sort_order: 0, translations: { uz: { name: '', title: '', quote: '' }, ru: { name: '', title: '', quote: '' } } })
const personDraft = ref(blankPerson())
const personRows = computed(() => people.value)
const message = ref('')
async function refresh() { error.value = ''; try { const [nextNews, nextPeople, nextSettings] = await Promise.all([getAllNews(), getPeople(), getSettings()]); news.value = nextNews; people.value = nextPeople; Object.assign(settings, nextSettings) } catch (e) { error.value = e.message } }
async function login() { busy.value = true; error.value = ''; try { await signIn(email.value, password.value); if (!hasContentRole()) { clearAdminSession(); throw new Error('У этой учётной записи нет прав администратора.') } authenticated.value = true; await refresh() } catch (e) { error.value = e.message } finally { busy.value = false } }
function edit(item) { editing.value = JSON.parse(JSON.stringify(item)); for (const lang of ['uz', 'ru']) editing.value.translations[lang].body = [editing.value.translations[lang].body.join('\n\n')]; editorOpen.value = true }
function createNews() { editing.value = blankNews(); editorOpen.value = true }
function addParagraph(lang) { editing.value.translations[lang].body.push('') }
async function submitNews() { busy.value = true; error.value = ''; try { const draft = JSON.parse(JSON.stringify(editing.value)); for (const lang of ['uz', 'ru']) draft.translations[lang].body = draft.translations[lang].body[0].split(/\n\s*\n/).map(text => text.trim()).filter(Boolean); draft.slug ||= draft.translations.uz.title.toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || crypto.randomUUID(); await saveNews(draft); editorOpen.value = false; await refresh(); message.value = labels.value.savedNews } catch (e) { error.value = e.message } finally { busy.value = false } }
async function chooseNewsImage(event) { const file = event.target.files?.[0]; event.target.value = ''; if (!file) return; imageBusy.value = true; error.value = ''; try { editing.value.cover.imageUrl = await uploadNewsImage(file); editing.value.cover.type = 'image' } catch (e) { error.value = e.message } finally { imageBusy.value = false } }
async function removeNews(item) { if (!confirm(`Удалить новость «${item.translations?.ru?.title || item.slug}»?`)) return; try { await deleteNews(item.id); await refresh() } catch (e) { error.value = e.message } }
function editPerson(person) { personDraft.value = JSON.parse(JSON.stringify(person)); editing.value = person; }
function createPerson() { personDraft.value = blankPerson(); editing.value = { type: 'person-new' } }
async function submitPerson() { busy.value = true; error.value = ''; try { await savePerson(personDraft.value); editing.value = null; await refresh() } catch (e) { error.value = e.message } finally { busy.value = false } }
async function removePerson(person) { if (!confirm('Удалить эту запись?')) return; try { await deletePerson(person.id); await refresh() } catch (e) { error.value = e.message } }
async function submitSettings() { busy.value = true; error.value = ''; try { await saveSettings({ ...settings }); message.value = labels.value.savedSchool } catch (e) { error.value = e.message } finally { busy.value = false } }
function logout() { clearAdminSession(); authenticated.value = false; router.replace('/') }
onMounted(() => { if (authenticated.value) refresh() })
</script>

<template>
  <main class="admin-page">
    <section v-if="!authenticated" class="admin-login"><a class="admin-back" href="#/">{{ labels.back }}</a><div class="admin-login-card"><div class="admin-login-tools"><span class="admin-mark">13</span><div class="admin-language-switch" aria-label="Language"><button :class="{selected:uiLanguage==='ru'}" @click="setUiLanguage('ru')">RU</button><span>/</span><button :class="{selected:uiLanguage==='uz'}" @click="setUiLanguage('uz')">UZ</button></div></div><p class="eyebrow">13-MAKTAB · CMS</p><h1>{{ labels.login }}</h1><p class="admin-muted">{{ labels.loginHint }}</p><form @submit.prevent="login"><label>{{ labels.email }}<input v-model="email" type="email" autocomplete="username" required></label><label>{{ labels.password }}<input v-model="password" type="password" autocomplete="current-password" required></label><p v-if="!configured" class="admin-hint">Подключите Supabase в <code>.env.local</code>. <a href="#/admin?demo=1" @click.prevent="authenticated = true; refresh()">Продолжить локально</a>.</p><button class="admin-primary" :disabled="busy || !configured">{{ busy ? labels.signingIn : labels.signIn }}</button><p v-if="error" class="admin-error">{{ error }}</p></form></div></section>
    <section v-else class="admin-layout"><aside class="admin-sidebar"><a class="admin-brand" href="#/"><span class="admin-mark">13</span><span>13-MAKTAB<small>ADMIN PANEL</small></span></a><p class="admin-nav-label">{{ labels.manage }}</p><button v-for="item in [{id:'news',label:labels.news,icon:'✳'},{id:'people',label:labels.people,icon:'♙'},{id:'school',label:labels.school,icon:'⌂'}]" :key="item.id" :class="{active:tab===item.id}" @click="tab=item.id">{{ item.icon }} <span>{{ item.label }}</span><b v-if="item.id==='news'">{{ news.length }}</b></button><div class="admin-sidebar-bottom"><a href="#/">{{ labels.viewSite }}</a><button @click="logout">{{ labels.logout }}</button></div></aside>
      <div class="admin-main"><header class="admin-topbar"><div><span>13-MAKTAB / ADMIN</span><h1>{{ tab==='news'?labels.news:tab==='people'?labels.people:labels.school }}</h1></div><div class="admin-topbar-tools"><div class="admin-language-switch" aria-label="Language"><button :class="{selected:uiLanguage==='ru'}" @click="setUiLanguage('ru')">RU</button><span>/</span><button :class="{selected:uiLanguage==='uz'}" @click="setUiLanguage('uz')">UZ</button></div><div class="admin-status"><i :class="configured?'is-connected':''"></i>{{ configured?labels.connected:labels.local }}</div></div></header><div v-if="!configured" class="admin-banner">{{ labels.demo }} <span v-if="uiLanguage==='ru'">Задайте ключи Supabase, чтобы включить общую базу.</span></div><p v-if="error" class="admin-error admin-alert">{{ error }}</p><p v-if="message" class="admin-success">{{ message }}</p>
        <section v-if="tab==='news'" class="admin-content"><div class="admin-section-head"><div><h2>{{ labels.allNews }}</h2><p>{{ labels.newsHint }}</p></div><button class="admin-primary" @click="createNews">{{ labels.newNews }}</button></div><div v-if="editorOpen" class="admin-panel editor-panel"><div class="admin-section-head"><h2>{{ editing.id?labels.editNews:labels.newNews }}</h2><button class="admin-quiet" @click="editorOpen=false">{{ labels.close }}</button></div><div class="admin-form-grid"><label>{{ uiLanguage==='uz'?'Holat':'Статус' }}<select v-model="editing.status"><option value="draft">{{ labels.draft }}</option><option value="published">{{ labels.published }}</option></select></label><label>{{ labels.category }}<select v-model="editing.category"><option value="school">{{ labels.categorySchool }}</option><option value="students">{{ labels.categoryStudents }}</option><option value="events">{{ labels.categoryEvents }}</option></select></label><label>{{ labels.slug }}<input v-model="editing.slug" :placeholder="uiLanguage==='uz'?'Sarlavhadan yaratiladi':'Создаётся из заголовка'"></label></div><div class="admin-news-image"><div class="admin-image-preview"><img v-if="editing.cover.imageUrl" :src="editing.cover.imageUrl" alt="News cover preview"><div v-else class="admin-image-empty"><span>✳</span><small>{{ labels.photo }}</small></div></div><div class="admin-image-controls"><strong>{{ labels.photo }}</strong><p>{{ labels.photoHint }}</p><label class="admin-upload-button">{{ imageBusy?(uiLanguage==='uz'?'Yuklanmoqda…':'Загружаем…'):labels.upload }}<input type="file" accept="image/jpeg,image/png,image/webp" :disabled="imageBusy" @change="chooseNewsImage"></label><button v-if="editing.cover.imageUrl" type="button" class="admin-quiet" @click="editing.cover.imageUrl='';editing.cover.type='pattern'">{{ labels.removePhoto }}</button></div></div><div class="admin-lang-grid"><fieldset v-for="lang in ['uz','ru']" :key="lang"><legend>{{ lang==='uz'?'O‘zbekcha':'Русский' }}</legend><label>{{ labels.title }}<input v-model="editing.translations[lang].title" required></label><label>{{ labels.categoryName }}<input v-model="editing.translations[lang].categoryLabel"></label><label>{{ labels.excerpt }}<textarea v-model="editing.translations[lang].excerpt" rows="2"></textarea></label><label>{{ labels.body }}<textarea v-model="editing.translations[lang].body[0]" rows="5" :placeholder="labels.bodyHint"></textarea></label></fieldset></div><button class="admin-primary" :disabled="busy||imageBusy" @click="submitNews">{{ labels.saveNews }}</button></div><div class="admin-panel admin-table"><article v-for="item in news" :key="item.id" class="admin-row"><div class="admin-row-icon admin-news-thumb"><img v-if="item.cover?.imageUrl" :src="item.cover.imageUrl" alt=""><span v-else>{{ item.category==='events'?'✦':item.category==='students'?'♙':'✺' }}</span></div><div class="admin-row-copy"><span :class="['admin-badge',item.status]">{{ item.status==='published'?labels.published:labels.draft }}</span><h3>{{ item.translations?.ru?.title || item.translations?.uz?.title || item.slug }}</h3><p>{{ item.slug }} · {{ item.category }}</p></div><div class="admin-row-actions"><button @click="edit(item)">{{ labels.edit }}</button><button class="danger" @click="removeNews(item)">{{ labels.delete }}</button></div></article><p v-if="!news.length" class="admin-empty">{{ labels.noNews }}</p></div></section>
        <section v-if="tab==='people'" class="admin-content"><div class="admin-section-head"><div><h2>{{ labels.teamTitle }}</h2><p>{{ labels.teamHint }}</p></div><button class="admin-primary" @click="createPerson">{{ labels.addPerson }}</button></div><div v-if="editing && (editing.type==='person-new' || editing.role)" class="admin-panel editor-panel"><div class="admin-section-head"><h2>{{ labels.personCard }}</h2><button class="admin-quiet" @click="editing=null">{{ labels.close }}</button></div><div class="admin-form-grid"><label>{{ labels.type }}<select v-model="personDraft.role"><option value="teacher">{{ labels.teacher }}</option><option value="student">{{ labels.student }}</option></select></label><label>{{ labels.personPhoto }}<input v-model="personDraft.photo_url" placeholder="https://…"></label><label>{{ labels.order }}<input v-model.number="personDraft.sort_order" type="number"></label></div><div class="admin-lang-grid"><fieldset v-for="lang in ['uz','ru']" :key="lang"><legend>{{ lang==='uz'?'O‘zbekcha':'Русский' }}</legend><label>{{ labels.name }}<input v-model="personDraft.translations[lang].name"></label><label>{{ labels.role }}<input v-model="personDraft.translations[lang].title"></label><label>{{ labels.quote }}<textarea v-model="personDraft.translations[lang].quote" rows="3"></textarea></label></fieldset></div><button class="admin-primary" :disabled="busy" @click="submitPerson">{{ labels.save }}</button></div><div class="admin-panel admin-table"><article v-for="person in personRows" :key="person.id" class="admin-row"><div class="admin-row-icon">{{ person.role==='student'?'♙':'✳' }}</div><div class="admin-row-copy"><span class="admin-badge published">{{ person.role==='student'?labels.student:labels.teacher }}</span><h3>{{ person.translations?.ru?.name || person.translations?.uz?.name }}</h3><p>{{ person.translations?.ru?.title || person.translations?.uz?.title }}</p></div><div class="admin-row-actions"><button @click="editPerson(person)">{{ labels.edit }}</button><button class="danger" @click="removePerson(person)">{{ labels.delete }}</button></div></article><p v-if="!people.length" class="admin-empty">{{ labels.noPeople }}</p></div></section>
        <section v-if="tab==='school'" class="admin-content"><div class="admin-section-head"><div><h2>{{ labels.schoolTitle }}</h2><p>{{ labels.schoolHint }}</p></div></div><div class="admin-panel school-editor"><fieldset><legend>O‘zbekcha</legend><label>{{ labels.heading }}<input v-model="settings.about_title_uz"></label><label>{{ labels.text }}<textarea v-model="settings.about_text_uz" rows="5"></textarea></label><label>{{ labels.stats }} 1<input v-model="settings.stat_label_1_uz"></label><label>{{ labels.stats }} 2<input v-model="settings.stat_label_2_uz"></label><label>{{ labels.stats }} 3<input v-model="settings.stat_label_3_uz"></label></fieldset><fieldset><legend>Русский</legend><label>{{ labels.heading }}<input v-model="settings.about_title_ru"></label><label>{{ labels.text }}<textarea v-model="settings.about_text_ru" rows="5"></textarea></label><label>{{ labels.stats }} 1<input v-model="settings.stat_label_1_ru"></label><label>{{ labels.stats }} 2<input v-model="settings.stat_label_2_ru"></label><label>{{ labels.stats }} 3<input v-model="settings.stat_label_3_ru"></label></fieldset><button class="admin-primary" :disabled="busy" @click="submitSettings">{{ labels.saveSchool }}</button></div></section>
      </div>
    </section>
  </main>
</template>
